begin;select plan(5);insert into auth.users(id,email)values('00000000-0000-0000-0000-000000000081','review-test@example.com');insert into public.profiles(id,email,display_name,global_role,status)values('00000000-0000-0000-0000-000000000081','review-test@example.com','Review Test','ADMIN','ACTIVE');insert into public.interns(id,name,created_by,updated_by)values('30000000-0000-0000-0000-000000000081','Review Intern','00000000-0000-0000-0000-000000000081','00000000-0000-0000-0000-000000000081');set local role authenticated;set local request.jwt.claim.sub='00000000-0000-0000-0000-000000000081';
